import{_ as o,o as d,c as t,ag as a}from"./chunks/framework.BaNuf0sO.js";const u=JSON.parse('{"title":"AppSidebar（侧边栏积木）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/app-layout/docs/README-AppSidebar.md","filePath":"docs/core/src/components/app-layout/docs/README-AppSidebar.md"}'),s={name:"docs/core/src/components/app-layout/docs/README-AppSidebar.md"};function i(r,e,l,c,p,n){return d(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="appsidebar-侧边栏积木" tabindex="-1">AppSidebar（侧边栏积木） <a class="header-anchor" href="#appsidebar-侧边栏积木" aria-label="Permalink to &quot;AppSidebar（侧边栏积木）&quot;">​</a></h1><blockquote><p>左侧栏积木：折叠把手 + MenuTree 菜单渲染（树形 / 分组双形态）+ #top/#bottom 高度自撑插槽；可 aboveHeader 悬浮盖顶。 范式页：<code>apps/reference/src/pages/app-layout/shell/</code>（DemoCustomShell 自供 shell 积木直引）、<code>apps/reference/src/pages/app-layout/layout/</code>（NoSidebar 显隐变体）</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>何时用</strong>：内置 AppShell 经典布局已直引；自供 shell 时按需复用（菜单/折叠把手/品牌位自由组合）</li><li><code>show</code> 控制显隐（含折叠把手渲染开关）——false 即不渲染整栏</li><li><code>aboveHeader</code> 时 z-index 2 盖 header（AppLayout 另有 <code>sidebarAboveHeader</code> prop 同源传递）</li><li>#top/#bottom 高度自撑（WatchSize 反推 shim 边界）——品牌区/挂件放 #top，底部操作放 #bottom</li><li>菜单形态由 <strong>bridge 配置</strong>驱动（非 prop）：<code>bridge.APP_LAYOUT_SIDEBAR_CONFIG.menuGroupMode</code>（缺省 <code>false</code>）</li></ul><h2 id="菜单形态-树形-默认-分组" tabindex="-1">菜单形态：树形（默认）/ 分组 <a class="header-anchor" href="#菜单形态-树形-默认-分组" aria-label="Permalink to &quot;菜单形态：树形（默认）/ 分组&quot;">​</a></h2><p><code>menuGroupMode</code> 落在 <code>APP_LAYOUT_SIDEBAR_CONFIG</code>（<code>createCoreBridge</code> 初始化传入，缺省 <code>false</code>；因在 <code>UpdatableConfigKey</code> 联合内，亦可 <code>bridge.update(&quot;APP_LAYOUT_SIDEBAR_CONFIG&quot;, { menuGroupMode: true })</code> 运行时切换）。AppSidebar 内部读它，<strong>不开放同名 prop</strong>——与 <code>collapse</code> 读 <code>appStore.sidebarIsCollapse</code> 同范式，业务侧统一在 bridge 一处配置。</p><table tabindex="0"><thead><tr><th></th><th><code>menuGroupMode: false</code>（默认）</th><th><code>menuGroupMode: true</code></th></tr></thead><tbody><tr><td>菜单渲染</td><td>MenuTree 树形（父级手风琴，默认收起）</td><td>MenuTree 分组（父级 = 小字号弱色分组标题，子项常驻全展开）</td></tr><tr><td>折叠把手 <code>AppCollapseToggle</code></td><td>渲染</td><td><strong>不渲染</strong>（<code>show=false</code>）</td></tr><tr><td>侧栏宽度</td><td>随折叠态在 <code>width</code> / <code>collapseWidth</code> 间切换</td><td>恒取 <code>width</code>（展开态）</td></tr><tr><td><code>bridge.layout.sidebarCollapsed</code></td><td>生效</td><td><strong>读取被屏蔽</strong>，但持久化值原样保留</td></tr></tbody></table><p><strong>为什么分组形态没有折叠把手</strong>：分组形态的前提是「全展开常驻」，与折叠成图标栏语义互斥；且 EP 的 <code>--collapse</code> 规则对 <code>el-menu-item-group</code> 支持不全（标题不隐藏、组内叶子不居中），窄栏必然错乱。故直接关掉该形态下的折叠能力，而非去打 EP 补丁。</p><p><strong>⚠️ 折叠持久化的锁死风险与规避</strong>（实现约束，[MUST] 守）：<code>bridge.layout</code> 把 <code>sidebarCollapsed</code> 持久化进 localStorage。若用户上次折叠过（落盘 <code>true</code>），开发者随后打开 <code>menuGroupMode</code>，侧栏会以 <code>collapseWidth</code> 窄条渲染却<strong>没有把手可展开 → 永久锁死</strong>。规避方式：<code>menuGroupMode</code> 为真时在 <code>store/app.ts</code> 单点把折叠态<strong>读取</strong>强制为 <code>false</code>（<code>sidebarWidth</code> 与 <code>sidebarIsCollapse</code> 两处共用同一 computed），<strong>[MUST NOT] 写回</strong> <code>bridge.layout.setSidebarCollapse</code>——用户的折叠偏好原样留在存储里，关掉分组形态后照常恢复。</p><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><p>内置 AppShell 经典布局已直引——自供 shell 需要菜单侧栏时最小直引（三必填 prop）：</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AppSidebar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">showSidebar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">menus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sidebarMenus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">menuFlatList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">menuFlatList</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>show</code> / <code>menus</code>（MenuTree 渲染）/ <code>menuFlatList</code>（内部匹配）三必填</li><li>折叠把手状态由族内共享（<code>AppCollapseToggle</code> 内部积木），折叠后仅把手占位——零配置</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong><code>#top</code> / <code>#bottom</code> 高度自撑插槽按需</strong>：默认零配置即菜单栏可用；仅当需要品牌区/挂件（<code>#top</code>）或底部操作区（<code>#bottom</code>）才填——高度自撑（WatchSize 反推 shim 边界），放多少内容撑多高。</li><li><strong><code>aboveHeader</code> 默认关</strong>：仅当 sidebar 需要 z-index 2 盖住 header 悬浮时开（与 AppLayout <code>sidebarAboveHeader</code> 同源传递，自供 shell 时对齐）。</li><li><strong><code>menuGroupMode</code> 默认关（树形）即够用</strong>：仅当菜单量小（经验值 ≤ 25 叶子）/ 层级浅、要求零点击看见全部导航才开；量大或层级深仍用树形，否则全展开会变成长滚动条。开启后自动失去折叠能力（见上表）。</li><li><code>show=false</code> 整栏不渲染（含折叠把手）——「收起但保留把手」场景走折叠态而非 <code>show=false</code>。</li><li><strong>完整能力演示</strong>（DemoCustomShell 槽转发范式 + NoSidebar 变体）：<code>apps/reference/src/pages/app-layout/shell/</code>、<code>apps/reference/src/pages/app-layout/layout/</code></li></ul><h2 id="面貌-背景-圆角-无横向内呼吸" tabindex="-1">面貌（背景 / 圆角 / 无横向内呼吸） <a class="header-anchor" href="#面貌-背景-圆角-无横向内呼吸" aria-label="Permalink to &quot;面貌（背景 / 圆角 / 无横向内呼吸）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>默认</th><th>覆盖法</th></tr></thead><tbody><tr><td>背景</td><td><code>APP_LAYOUT_SIDEBAR_CONFIG.background ?? 主题 bodyColor</code></td><td>配 <code>background</code></td></tr><tr><td>圆角</td><td><code>var(--dc-core-radius, var(--el-border-radius-base))</code>（随主题）</td><td><code>APP_LAYOUT_SIDEBAR_CONFIG.style.borderRadius</code></td></tr><tr><td>横向内呼吸</td><td><strong>无，[MUST NOT] 补</strong></td><td>——</td></tr></tbody></table><ul><li>圆角与背景<strong>同源</strong>（都在 <code>appStore.sidebarStyle</code> 这一份 inline style 里），默认值写在 <code>...cfg.style</code> 展开之前 ⇒ 逃生舱同名键恒赢。</li><li>🔴 <strong>为什么不像 header / footer 那样补横向 padding</strong>：侧栏里装的是菜单树， <code>.el-menu-item</code> 自带 <code>padding: 0 var(--el-menu-base-level-padding)</code>（默认 20px）—— 外层再让一份就是<strong>双份</strong>，且折叠成图标栏时会把图标挤离中线。</li><li>🔴 <strong>圆角要看得见，靠的是内部那层裁切盒</strong>（<code>.app-sidebar-clip</code>，<code>inset: 0</code> + <code>overflow: hidden</code><ul><li><code>border-radius: inherit</code>）：根盒 [MUST] 保持 <code>overflow: visible</code>（折叠把手悬挂在外缘）， 故根盒自己裁不了——而 <code>el-menu</code> 自带背景色会直接盖住四角。[MUST NOT] 把 clip 层删掉当冗余。</li></ul></li><li>收起态（<code>showSidebar=false</code> → 宽收 0）零面积、不留圆角残影。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>show</code></td><td><code>boolean</code>（必填）</td><td>—</td><td>显隐（含折叠把手渲染开关）</td></tr><tr><td><code>aboveHeader</code></td><td><code>boolean</code></td><td><code>false</code></td><td>z-index 2 盖 header</td></tr><tr><td><code>menus</code></td><td><code>RouteMetaResolveRaw[]</code>（必填）</td><td>—</td><td>sidebar 区菜单（MenuTree 渲染）</td></tr><tr><td><code>menuFlatList</code></td><td><code>RouteMetaResolveRaw[]</code>（必填）</td><td>—</td><td>扁平菜单</td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p>无</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#top</code> / <code>#bottom</code></td><td>无</td><td>高度自撑（WatchSize 反推 shim 边界）——品牌区/挂件 / 底部操作区</td></tr></tbody></table><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><code>show=false</code> 时折叠把手也随整栏不渲染（把手渲染开关即 show）——「收起但保留把手」场景应走折叠态而非 show=false</li><li><strong><code>menuGroupMode</code> 下还想保留折叠把手</strong>：两者语义互斥且 EP 折叠态不支持分组，[MUST NOT] 强开</li><li><strong><code>menuGroupMode</code> 下调 <code>bridge.layout.setSidebarCollapse</code> / <code>appStore.changeSidebarCollapseStatus</code></strong>：调用不报错但视觉无效（读取被屏蔽），属无效操作</li><li><strong>给 AppSidebar 加同名 <code>menuGroupMode</code> prop 覆盖 bridge</strong>：[MUST NOT]——形态是全 app 一致的布局配置，双真相源会让自供 shell 与内置 shell 表现分叉</li><li><code>aboveHeader</code> 与 AppLayout <code>sidebarAboveHeader</code> 语义一致，自供 shell 时两者对齐（DemoCustomShell 透传范式）</li><li>折叠/展开动画由族内积木承担，[MUST NOT] 自造折叠逻辑</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>折叠积木：<code>AppCollapseToggle</code>（族内共享，AppSidebar/AppAside 内部使用，未导出）</li><li>菜单积木：<code>MenuTree</code>（menu 族，<code>groupMode</code> 双形态详见 <a href="/done-coding-showcase/docs/core/src/components/menu/README.html">menu 族文档</a>）</li><li>配置真源：<code>APP_LAYOUT_SIDEBAR_CONFIG</code>（bridge，见 <a href="/done-coding-showcase/docs/core/src/bridge/docs/README.html">bridge 文档</a>）</li><li>右侧对称积木：<code>AppAside</code></li><li>内容锚：<code>#brand</code> 等（落位见 AppLayout 文档）</li><li>范式页：<code>apps/reference/src/pages/app-layout/shell/</code>、<code>apps/reference/src/pages/app-layout/layout/</code></li></ul>',33)])])}const b=o(s,[["render",i]]);export{u as __pageData,b as default};
